export type ChannelKey = 'whatsapp' | 'instagram' | 'messenger' | 'facebook' | 'tiktok' | 'email';
export type ActionId = 'send_text' | 'send_audio' | 'send_image' | 'send_video' | 'send_template' | 'send_document' | 'proactive_outbound' | 'broadcast' | 'transfer_to_human' | 'apply_discount' | 'schedule_followup' | 'create_payment_link';
export type ToneId = 'consultivo' | 'formal' | 'direto' | 'acolhedor' | 'coloquial';
export type FormatId = 'text' | 'audio' | 'image' | 'video' | 'document' | 'template' | 'html_rich';

export interface ChannelRepertoire {
  channel: ChannelKey;
  actions: ActionId[];
  tones: ToneId[];
  formats: FormatId[];
  proactiveOutboundAllowed: boolean;
  proactiveWindowHours: number | null; // 24 for Instagram/Messenger, null for unrestricted
  audioInboundOnly: boolean;            // TikTok if not approved for outbound
}

export const CHANNEL_REPERTOIRE: Record<ChannelKey, ChannelRepertoire> = {
  whatsapp: { ..., actions: includes audio + template + media + proactive },
  instagram: { ..., proactiveWindowHours: 24 },
  messenger: { ..., proactiveWindowHours: 24 },
  facebook: ... ,
  tiktok: { ..., proactiveOutboundAllowed: false (default; configurable via env TIKTOK_OUTBOUND_APPROVED) },
  email: { ..., formats: ['text', 'html_rich'] /* NO audio */ }
};

export function repertoireFor(channel: string): ChannelRepertoire | null;
export function canChannelDoAction(channel: string, action: ActionId): boolean;
export function allowedFormatsFor(channel: string): FormatId[];
export function allowedTonesFor(channel: string): ToneId[];

